public Page<SaleResponseDto> filterStyles(SaleFilterRequestDto filterRequestDto, Pageable pageable) {
    QSale style = QSale.sale;
    QProfile profile = QProfile.profile;
    QSaleFaqItem styleOrderItem = QSaleFaqItem.saleFaqItem;
    QFaqItem orderItem = QFaqItem.faqItem;
    QMediaUrl mediaUrl = QMediaUrl.mediaUrl;
    QUserSize productSize = QUserSize.userSize;
    QUserColor productColor = QUserColor.userColor;
    QUser product = QUser.user;
